// Global Memory fallback store
let memoryStore = JSON.parse(JSON.stringify(INITIAL_CONFIG));

async function getStore(env) {
  if (env && env.ROCCO_KV) {
    try {
      const data = await env.ROCCO_KV.get("rocco_store", "json");
      if (data) return data;
    } catch(e) {}
  }
  return memoryStore;
}

async function saveStore(env, data) {
  memoryStore = data;
  if (env && env.ROCCO_KV) {
    try {
      await env.ROCCO_KV.put("rocco_store", JSON.stringify(data));
    } catch(e) {}
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const pathname = url.pathname.toLowerCase().replace(/\/+$/, '') || '/';

    // 1. CORS Preflight
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: getCorsHeaders()
      });
    }

    try {
      // 2. EXTENSION REST API ENDPOINTS
      if (pathname === '/api/props.php' || pathname === '/api/props') {
        return handlePropsRequest(url, env);
      }
      if (pathname === '/api/auth.php' || pathname === '/api/auth') {
        return handleAuthRequest(request, url, env);
      }
      if (pathname === '/api/monetization.php' || pathname === '/api/monetization') {
        return handleMonetizationRequest(request, url, env);
      }
      if (pathname === '/api/balance.php' || pathname === '/api/balance') {
        return handleBalanceRequest(request, url, env);
      }
      if (pathname === '/api/import.php' || pathname === '/api/import') {
        return jsonResponse({ success: true, message: "Asset ready for import." });
      }

      // 3. SETUP DOWNLOAD REDIRECT
      if (pathname === '/download') {
        const store = await getStore(env);
        return Response.redirect(store.download_url || INITIAL_CONFIG.download_url, 302);
      }

      // 4. PRIVATE ADMIN ACTIONS & AUTH (AJAX)
      if (pathname === (ADMIN_ROUTE + '/api/action').toLowerCase()) {
        return handleAdminAction(request, env);
      }
      if (pathname === (ADMIN_ROUTE + '/api/login').toLowerCase()) {
        return handleAdminLogin(request, env);
      }

      // 5. PRIVATE ADMIN DASHBOARD
      if (pathname === ADMIN_ROUTE.toLowerCase()) {
        return handleAdminDashboard(request, url, env);
      }

      // 6. BLOCK PUBLIC ACCESS TO OLD /admin WITH 404
      if (pathname === '/admin' || pathname === '/admin/index.php' || pathname.startsWith('/admin/')) {
        return new Response("404 Not Found - The requested URL was not found on this server.", {
          status: 404,
          headers: { "Content-Type": "text/plain; charset=utf-8" }
        });
      }

      // 7. PUBLIC SOFTWARE LANDING PAGE (Root /) - EXACT ORIGINAL DESIGN
      if (pathname === '/' || pathname === '/index.html' || pathname === '/home') {
        return handleLandingPage(request, url, env);
      }

      return jsonResponse({ success: false, message: "Endpoint not found" }, 404);

    } catch (err) {
      return jsonResponse({ success: false, error: err.message }, 500);
    }
  }
};

