async function handleLandingPage(request, url, env) {
  const store = await getStore(env);
  const downloadUrl = store.download_url || INITIAL_CONFIG.download_url;

  // Ensure download buttons trigger the real download URL
  let html = ORIGINAL_LANDING_HTML.replace(/href="\/download"/g, 'href="' + downloadUrl + '"');

  return new Response(html, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      ...getCorsHeaders()
    }
  });
}

